25	pub fn cascade_action(kind: DepKind, coverage: Coverage, source: Severity, cfg: &CascadeConfig) -> CascadeDecision {
26	    use Coverage::*;
27	    use DepKind::*;
28	
29	    let effective = match (cfg.mode, coverage) {
30	        (CascadeMode::Always, _) => DoesNotCover,
31	        (CascadeMode::OutOfRange, Covers) => Covers,
32	        (CascadeMode::OutOfRange, DoesNotCover) => DoesNotCover,
33	        (CascadeMode::OutOfRange, Unknown) => Covers,
34	    };
35	
36	    let rewrite = matches!(coverage, DoesNotCover);
37	
38	    let (severity, governed_by, escalated) = match (kind, effective) {
39	        (Runtime | Optional | Build, Covers) => (Severity::None, None, false),
40	        (Runtime | Optional | Build, DoesNotCover) => (
41	            cfg.bump_severity.as_severity(),
42	            Some(ConfigKey::CASCADE_BUMP_SEVERITY),
43	            false,
44	        ),
45	        (Peer, Covers) => (Severity::None, None, false),
46	        (Peer, DoesNotCover)
47	            if cfg.peer_escalation
48	                && matches!(coverage, DoesNotCover)
49	                && matches!(source, Severity::Minor | Severity::Major) =>
50	        {
51	            (Severity::Major, Some(ConfigKey::CASCADE_PEER_ESCALATION), true)
52	        }
53	        (Peer, DoesNotCover) => (
54	            cfg.bump_severity.as_severity(),
55	            Some(ConfigKey::CASCADE_BUMP_SEVERITY),
56	            false,
57	        ),
58	        (Dev, _) => (Severity::None, None, false),
59	        _ => (Severity::None, None, false),
60	    };
61	
62	    let governed_by = match (cfg.mode, coverage, severity) {
63	        (CascadeMode::Always, Covers | Unknown, s) if s != Severity::None => Some(ConfigKey::CASCADE_MODE),
64	        _ => governed_by,
65	    };
66	
67	    CascadeDecision {
68	        severity,
69	        rewrite,
70	        governed_by,
71	        escalated,
72	        unknown_coverage: matches!(coverage, Unknown),
73	    }
74	}
