159	/// Propagates `input.seed`'s severities outward to dependents until no
160	/// target version changes, or `convergence_bound`'s iteration cap is
161	/// exceeded ([`GraphError::CascadeNotConverged`]) -- turns a would-be
162	/// infinite loop into a reportable bug, bound derived from package count.
163	///
164	/// One pass: pop a package, compute its bumped target, walk every
165	/// dependent edge, apply [`cascade_action`] to decide if that dependent's
166	/// severity/target changes and gets re-queued.
167	///
168	/// A genuine cross-grammar coverage failure (`coverage`'s `Err`, e.g.
169	/// SemVer target vs. PEP440 spec) aborts the whole cascade with
170	/// `Err(GraphError::GrammarMismatch)`. Soft instead: `Catalog`/`Opaque`
171	/// specs never have coverage tested (`coverage` returns `Unknown`
172	/// unconditionally), so they can't block anything -- `Catalog` gets
173	/// [`DiagnosticCode::CatalogSpecNotRewritten`], `Opaque` gets no
174	/// diagnostic. [`DiagnosticCode::RangeNotRoundTrippable`]'s real trigger
175	/// is a different step: [`rewrite_spec`], when a mechanical range rewrite
176	/// (not a coverage test) fails on an otherwise-known-coverage spec.
177	pub fn solve_cascade<D: DependencyResolver>(input: CascadeInput<'_, D>) -> Result<CascadeOutcome, GraphError> {
178	    let mut out = CascadeOutcome {
179	        severities: input.seed.clone(),
180	        reasons: input.reasons.clone(),
181	        ..Default::default()
182	    };
183	
184	    for (id, &sev) in input.seed {
185	        let t = bump_target(id, sev, &input)?;
186	        out.targets.insert(id.clone(), t);
187	    }
188	
189	    let mut worklist: BTreeSet<PackageId> = out.targets.keys().cloned().collect();
190	    let mut iterations = 0;
191	    let bound = convergence_bound(input.graph.packages().count());
192	
193	    let mut changed = true;
194	    while changed {
195	        changed = false;
196	
197	        while let Some(pkg) = worklist.pop_first() {
198	            iterations += 1;
199	            if iterations > bound {
200	                return Err(GraphError::CascadeNotConverged { iterations });
201	            }
202	
203	            let new_version = out.targets[&pkg].clone();
204	            let src_sev = out.severities[&pkg];
205	
206	            let dependents: Vec<DepEdge> = input.graph.dependents_of(&pkg).cloned().collect();
207	            for edge in dependents {
208	                let cov = coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
209	                    from: edge.from.clone(),
210	                    to: edge.to.clone(),
211	                    source,
212	                })?;
213	
214	                let d = cascade_action(edge.kind, cov, src_sev, input.cfg);
215	
216	                if d.unknown_coverage && !matches!(edge.spec, DepSpec::Opaque(_)) {
217	                    let code = match edge.spec {
218	                        DepSpec::Catalog(_) => DiagnosticCode::CatalogSpecNotRewritten,
219	                        _ => DiagnosticCode::RangeNotRoundTrippable,
220	                    };
221	                    out.diagnostics.push(Diagnostic {
222	                        code,
223	                        severity: DiagnosticSeverity::Warning,
224	                        message: format!(
225	                            "spec `{}` for `{}` could not be tested for coverage",
226	                            edge.spec.render(),
227	                            edge.to.display_name()
228	                        ),
229	                        package: Some(edge.from.clone()),
230	                        path: Some(edge.from_manifest.clone()),
231	                        governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
232	                        escalated_by: None,
233	                    });
234	                }
235	
236	                if d.rewrite {
237	                    let eco = edge.from.ecosystem().unwrap_or_else(|| {
238	                        if edge.from_manifest.to_string_lossy().ends_with("Cargo.toml") {
239	                            Ecosystem::Cargo
240	                        } else {
241	                            Ecosystem::Npm
242	                        }
243	                    });
244	                    match rewrite_spec(&edge.spec, &new_version, eco, input.cfg) {
245	                        RewriteOutcome::Rewritten(to_spec) => {
246	                            let key = RewriteKey {
247	                                target: if edge.inherited {
248	                                    DepWriteTarget::CargoWorkspaceDependency {
249	                                        root_manifest: edge.from_manifest.clone(),
250	                                    }
251	                                } else {
252	                                    DepWriteTarget::Manifest(edge.from_manifest.clone())
253	                                },
254	                                name: input
255	                                    .identity
256	                                    .native_name(&edge.to, eco)
257	                                    .map(str::to_string)
258	                                    .unwrap_or_else(|| edge.to.name().to_string()),
259	                                kind: if edge.inherited { None } else { Some(edge.kind) },
260	                            };
261	                            out.rewrites.insert(
262	                                key.clone(),
263	                                SpecRewrite {
264	                                    key,
265	                                    dependency: edge.to.clone(),
266	                                    from: edge.spec.clone(),
267	                                    to: to_spec,
268	                                },
269	                            );
270	                        }
271	                        RewriteOutcome::LeftAlone(dg) => {
272	                            out.diagnostics.push(dg);
273	                        }
274	                    }
275	                }
276	
277	                let cur_sev = out.severities.get(&edge.from).copied().unwrap_or(Severity::None);
278	                if d.severity > cur_sev {
279	                    raise(
280	                        &edge.from,
281	                        d.severity,
282	                        &d,
283	                        &pkg,
284	                        &edge,
285	                        &new_version,
286	                        &mut out,
287	                        input.groups,
288	                        &mut worklist,
289	                        &input,
290	                    )?;
291	                }
292	            }
293	        }
294	
295	        // Spec §G.6.7: Linked group release severity propagation
296	        for g in input.groups.linked.values() {
297	            let max_sev = g.max_severity(&out.severities);
298	            if max_sev == Severity::None {
299	                continue;
300	            }
301	
302	            // A member absent from `input.base` was removed from the
303	            // workspace but is still listed in the group config. Skip it
304	            // rather than let `bump_target` below hit `MissingField` --
305	            // mirrors the guard `aggregate::union_fixed`/`union_linked`
306	            // already apply before cascade convergence ever starts.
307	            let mut live_members = Vec::new();
308	            for id in g.package_members() {
309	                if !input.base.contains_key(id) {
310	                    out.diagnostics.push(Diagnostic {
311	                        code: DiagnosticCode::UnknownPackage,
312	                        severity: DiagnosticSeverity::Warning,
313	                        message: format!(
314	                            "Linked group `{}` references package `{}` which is not in the \
315	                             workspace; the stale group member is skipped. Remove it from \
316	                             callisto.toml to silence this warning.",
317	                            g.name,
318	                            id.display_name()
319	                        ),
320	                        package: Some(id.clone()),
321	                        path: None,
322	                        governed_by: Some(ConfigKey::LINKED_GROUP),
323	                        escalated_by: None,
324	                    });
325	                    continue;
326	                }
327	                live_members.push(id.clone());
328	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
329	                if max_sev > cur_sev {
330	                    out.severities.insert(id.clone(), max_sev);
331	                }
332	            }
333	
334	            let mut winner: Option<Version> = None;
335	            for id in &live_members {
336	                let candidate = bump_target(id, max_sev, &input)?;
337	                winner = Some(match winner {
338	                    None => candidate,
339	                    Some(best) => {
340	                        let cmp = Version::compare(&candidate, &best).map_err(|_grammar_mismatch| {
341	                            GraphError::GroupGrammarMismatch {
342	                                group: g.name.clone(),
343	                                members: live_members
344	                                    .iter()
345	                                    .filter_map(|m| out.targets.get(m).map(|v| (m.clone(), v.clone())))
346	                                    .collect(),
347	                            }
348	                        })?;
349	                        if cmp.is_gt() {
350	                            candidate
351	                        } else {
352	                            best
353	                        }
354	                    }
355	                });
356	            }
357	            let Some(winner) = winner else { continue };
358	
359	            for id in live_members {
360	                if out.targets.get(&id) != Some(&winner) {
361	                    out.targets.insert(id.clone(), winner.clone());
362	                    out.reasons
363	                        .insert(id.clone(), BumpReason::LinkedGroupUnion { group: g.name.clone() });
364	                    worklist.insert(id.clone());
365	                    changed = true;
366	                }
367	            }
368	        }
369	
370	        // Track 1: Fixed group convergence -- mirrors the Linked-group block
371	        // above but computes each group's shared target via
372	        // fixed_group_target instead of taking the max of independently
373	        // bumped per-member candidates.
374	        for g in input.groups.fixed.values() {
375	            let max_sev = g.max_severity(&out.severities);
376	            if max_sev == Severity::None {
377	                continue;
378	            }
379	
380	            // A member absent from `input.base` was removed from the
381	            // workspace but is still listed in the group config. Skip it
382	            // rather than let it flow into `out.severities`/`out.targets`,
383	            // which `plan_version`'s `pkg_map.get(id).copied().unwrap()`
384	            // (built only from live graph packages) would later panic on --
385	            // mirrors the guard `aggregate::union_fixed`/`union_linked` and
386	            // the Linked-group block above already apply.
387	            let mut live_members = Vec::new();
388	            for id in g.package_members() {
389	                if !input.base.contains_key(id) {
390	                    out.diagnostics.push(Diagnostic {
391	                        code: DiagnosticCode::UnknownPackage,
392	                        severity: DiagnosticSeverity::Warning,
393	                        message: format!(
394	                            "Fixed group `{}` references package `{}` which is not in the \
395	                             workspace; the stale group member is skipped. Remove it from \
396	                             callisto.toml to silence this warning.",
397	                            g.name,
398	                            id.display_name()
399	                        ),
400	                        package: Some(id.clone()),
401	                        path: None,
402	                        governed_by: Some(ConfigKey::FIXED_GROUP),
403	                        escalated_by: None,
404	                    });
405	                    continue;
406	                }
407	                live_members.push(id.clone());
408	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
409	                if max_sev > cur_sev {
410	                    out.severities.insert(id.clone(), max_sev);
411	                }
412	            }
413	
414	            let winner = crate::groups::fixed_group_target(g, input.base, max_sev, input.tags)?;
415	
416	            for id in live_members {
417	                if out.targets.get(&id) != Some(&winner) {
418	                    out.targets.insert(id.clone(), winner.clone());
419	                    out.reasons
420	                        .insert(id.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
421	                    worklist.insert(id.clone());
422	                    changed = true;
423	                }
424	            }
425	        }
426	    }
427	
428	    out.iterations = iterations;
429	    Ok(out)
430	}
