432	fn bump_target<D: DependencyResolver>(
433	    id: &PackageId,
434	    sev: Severity,
435	    input: &CascadeInput<'_, D>,
436	) -> Result<Version, GraphError> {
437	    let base = input.base.get(id).cloned().ok_or_else(|| {
438	        GraphError::Manifest(callisto_model::ManifestError::MissingField {
439	            path: PathBuf::from(id.name()),
440	            field: "version",
441	        })
442	    })?;
443	    let versioning: &dyn callisto_format::Versioning = match base.grammar() {
444	        callisto_model::VersionGrammar::Pep440 => &callisto_format::Pep440Versioning,
445	        _ => &callisto_format::SemVerVersioning,
446	    };
447	
448	    if let Some(pre) = input.pre {
449	        if pre.mode == callisto_format::PreMode::Pre {
450	            let pinned_base = pre.initial_versions.get(id.name()).unwrap_or(&base);
451	            versioning
452	                .bump_prerelease(pinned_base, sev, &pre.tag, &base)
453	                .map_err(GraphError::Bump)
454	        } else {
455	            // PreMode::Exit: finalize the current pre-release to a stable version.
456	            // Bumping the on-disk pre-release version (e.g. "1.0.0-alpha.2") with
457	            // any severity that matches the pre-release target strips the tag and
458	            // produces the stable version (e.g. "1.0.0").
459	            versioning.bump(&base, sev).map_err(GraphError::Bump)
460	        }
461	    } else {
462	        versioning.bump(&base, sev).map_err(GraphError::Bump)
463	    }
464	}
