466	#[allow(clippy::too_many_arguments)]
467	fn raise<D: DependencyResolver>(
468	    pkg: &PackageId,
469	    sev: Severity,
470	    decision: &CascadeDecision,
471	    via: &PackageId,
472	    edge: &DepEdge,
473	    dependency_to: &Version,
474	    out: &mut CascadeOutcome,
475	    groups: &GroupTable,
476	    worklist: &mut BTreeSet<PackageId>,
477	    input: &CascadeInput<'_, D>,
478	) -> Result<bool, GraphError> {
479	    let cur_sev = out.severities.get(pkg).copied().unwrap_or(Severity::None);
480	    if sev <= cur_sev {
481	        return Ok(false);
482	    }
483	
484	    out.severities.insert(pkg.clone(), sev);
485	
486	    let new_reason = if decision.escalated {
487	        BumpReason::PeerEscalation {
488	            via: via.clone(),
489	            spec: edge.spec.render(),
490	        }
491	    } else {
492	        BumpReason::Cascade {
493	            via: via.clone(),
494	            dep_kind: edge.kind,
495	            spec: edge.spec.render(),
496	            dependency_to: dependency_to.clone(),
497	        }
498	    };
499	    out.reasons.insert(pkg.clone(), new_reason);
500	
501	    if let Some(ref gov) = decision.governed_by {
502	        out.governed_by.insert(pkg.clone(), gov.clone());
503	    }
504	
505	    let new_t = bump_target(pkg, sev, input)?;
506	    out.targets.insert(pkg.clone(), new_t);
507	    worklist.insert(pkg.clone());
508	
509	    for sib in groups.fixed_siblings(pkg) {
510	        let sib_sev = out.severities.get(sib).copied().unwrap_or(Severity::None);
511	        if sev > sib_sev {
512	            out.severities.insert(sib.clone(), sev);
513	            out.reasons.insert(
514	                sib.clone(),
515	                BumpReason::FixedGroupUnion {
516	                    group: groups.fixed_group_of(pkg).unwrap().name.clone(),
517	                },
518	            );
519	            let sib_t = bump_target(sib, sev, input)?;
520	            out.targets.insert(sib.clone(), sib_t);
521	            worklist.insert(sib.clone());
522	        }
523	    }
524	
525	    Ok(true)
526	}
