558	pub fn rewrite_spec(original: &DepSpec, new: &Version, eco: Ecosystem, cfg: &CascadeConfig) -> RewriteOutcome {
559	    if !cfg.preserve_npm_ranges && eco == Ecosystem::Npm {
560	        return RewriteOutcome::Rewritten(DepSpec::Exact(new.clone()));
561	    }
562	
563	    if let Some(rewritten) = callisto_manifests::round_trip(eco, original, new) {
564	        RewriteOutcome::Rewritten(rewritten)
565	    } else {
566	        RewriteOutcome::LeftAlone(Diagnostic {
567	            code: DiagnosticCode::RangeNotRoundTrippable,
568	            severity: DiagnosticSeverity::Warning,
569	            message: format!(
570	                "spec `{}` could not be round-tripped toward version `{}`",
571	                original.render(),
572	                new.render()
573	            ),
574	            package: None,
575	            path: None,
576	            governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
577	            escalated_by: None,
578	        })
579	    }
580	}
