582	#[cfg(test)]
583	mod tests {
584	    use super::*;
585	    use callisto_model::{GroupKind, GroupName, Package, ReleaseTrigger, VersionGrammar};
586	
587	    use crate::config::{CascadeBumpSeverity, GroupDef, GroupMember};
588	
589	    /// §13 invariant 9 / §7.4 row 5 vs row 4: peer-dependency escalation to
590	    /// `Severity::Major` must only fire when the upstream (source) severity
591	    /// is non-patch (Minor or Major). A patch-severity source that leaves a
592	    /// peer spec out of range falls through to row 4 (`cfg.bump_severity`),
593	    /// not a manufactured Major bump -- `cascade_action`'s `source` parameter
594	    /// must actually gate the escalation, not just be accepted and ignored.
595	    #[test]
596	    fn cascade_action_peer_escalation_only_fires_for_non_patch_source() {
597	        let cfg = CascadeConfig {
598	            mode: CascadeMode::OutOfRange,
599	            bump_severity: CascadeBumpSeverity::Patch,
600	            peer_escalation: true,
601	            preserve_npm_ranges: false,
602	        };
603	
604	        // Patch-severity source: must NOT escalate to Major (row 4).
605	        let patch_decision = cascade_action(DepKind::Peer, Coverage::DoesNotCover, Severity::Patch, &cfg);
606	        assert_eq!(
607	            patch_decision.severity,
608	            Severity::Patch,
609	            "a patch-severity upstream source must not escalate a peer dependent to Major"
610	        );
611	        assert!(
612	            !patch_decision.escalated,
613	            "a patch-severity source must not set `escalated`"
614	        );
615	        assert_eq!(
616	            patch_decision.governed_by,
617	            Some(ConfigKey::CASCADE_BUMP_SEVERITY),
618	            "a patch-severity source falls through to the ordinary bump_severity row"
619	        );
620	
621	        // Minor-severity source: MUST escalate to Major (row 5).
622	        let minor_decision = cascade_action(DepKind::Peer, Coverage::DoesNotCover, Severity::Minor, &cfg);
623	        assert_eq!(
624	            minor_decision.severity,
625	            Severity::Major,
626	            "a non-patch (Minor) upstream source must escalate a peer dependent to Major"
627	        );
628	        assert!(minor_decision.escalated, "a non-patch source must set `escalated`");
629	        assert_eq!(minor_decision.governed_by, Some(ConfigKey::CASCADE_PEER_ESCALATION));
630	
631	        // Major-severity source: MUST also escalate to Major (row 5).
632	        let major_decision = cascade_action(DepKind::Peer, Coverage::DoesNotCover, Severity::Major, &cfg);
633	        assert_eq!(major_decision.severity, Severity::Major);
634	        assert!(major_decision.escalated);
635	
636	        // None-severity source: provably unreachable through run_cascade (every
637	        // write site into the severities map gates on `sev > Severity::None`
638	        // before inserting), but the match arm falls through to row 4 exactly
639	        // like Patch if it ever were reached -- exhaustive over the enum
640	        // rather than relying on that untested cross-function invariant.
641	        let none_decision = cascade_action(DepKind::Peer, Coverage::DoesNotCover, Severity::None, &cfg);
642	        assert_eq!(none_decision.severity, Severity::Patch);
643	        assert!(!none_decision.escalated);
644	    }
