737	    impl DependencyResolver for TestGraph {
738	        fn packages(&self) -> impl Iterator<Item = &Package> {
739	            self.packages.iter()
740	        }
741	
742	        fn dependencies_of(&self, id: &PackageId) -> impl Iterator<Item = &DepEdge> {
743	            // Return edges where `from == id` (id depends on the target).
744	            self.edges.iter().filter(move |e| &e.from == id)
