746	
747	        fn dependents_of(&self, id: &PackageId) -> impl Iterator<Item = &DepEdge> {
748	            // Return edges where `to == id` (i.e. the caller depends on id).
749	            self.edges.iter().filter(move |e| &e.to == id)
