             `1.0.0` fallback produced by picking the stale, unfiltered \
             member's (missing) slot in `base`"
        );
        assert!(
            !outcome.targets.contains_key(&pkg_stale),
            "stale fixed-group member must never receive a target: {:?}",
            outcome.targets
        );
    }
}

